(6806993, 1022247, 38162, '<td valign="top">lets hear it for the GTA!  great job on this.  car lights just right - hard to do.  10.</td>', 'lets hear it for the GTA!  great job on this.  car lights just right - hard to do.  10.', '2012-07-02 19:44:38.000000', NULL, 1),
(6806994, 1022979, 38162, '<td valign="top">horrid title overkill here.  10-2=8.  just a super mood shot - you put us THERE.  gl.</td>', 'horrid title overkill here.  10-2=8.  just a super mood shot - you put us THERE.  gl.', '2012-07-02 19:46:11.000000', NULL, 1),
(6807003, 1022947, 38162, '<td valign="top">the leaning tower of calgary?!  I would do the post with the objective of straightening the tower rather than the other structures.  1-stop of + exposure would also help.  try to warp tool and you may be fine with all structures.  7.  gl.</td>', 'the leaning tower of calgary?!  I would do the post with the objective of straightening the tower rather than the other structures.  1-stop of + exposure would also help.  try to warp tool and you may be fine with all structures.  7.  gl.', '2012-07-02 19:49:58.000000', NULL, 1),
(6807007, 1022886, 38162, '<td valign="top">the real 1-series bimmer!  great shot here.  club event?  whatever.  I cannot find any real faults to harp on.  9.  gl</td>', 'the real 1-series bimmer!  great shot here.  club event?  whatever.  I cannot find any real faults to harp on.  9.  gl', '2012-07-02 19:51:29.000000', NULL, 1),
(6807028, 1022870, 38162, '<td valign="top">its *savior* (or is your spelling brit, or french?).  nice concept.  a tad too centered for me.  needs some drama with that sky!  contast ... warmth - something.  that said, why not make it a killer B&amp;W?  you have a great beginning ... gl.</td>', 'its *savior* (or is your spelling brit, or french?).  nice concept.  a tad too centered for me.  needs some drama with that sky!  contast ... warmth - something.  that said, why not make it a killer B&W?  you have a great beginning ... gl.', '2012-07-02 20:05:48.000000', NULL, 1),
(6807030, 1022028, 38162, '<td valign="top">just what exactly does the frame add?  you have a nice start here.  gl.</td>', 'just what exactly does the frame add?  you have a nice start here.  gl.', '2012-07-02 20:07:03.000000', NULL, 1),
(6807031, 1023042, 38162, '<td valign="top">when did a contemporary charger become a classic?  that aside, you did some fine work with the white stuff underneath and overall lighting is superb.  needs either more color or a B&amp;W version - you took a middle road here that has no drama other than proper "pose" of the iron.  gl.</td>', 'when did a contemporary charger become a classic?  that aside, you did some fine work with the white stuff underneath and overall lighting is superb.  needs either more color or a B&W version - you took a middle road here that has no drama other than proper "pose" of the iron.  gl.', '2012-07-02 20:10:11.000000', NULL, 1),
(6807032, 1023043, 38162, '<td valign="top">overprocessed to the point of distraction; angle is fine and dramatic - good job.  border kills it off.  this would make a fine monochrome eh?  gl.</td>', 'overprocessed to the point of distraction; angle is fine and dramatic - good job.  border kills it off.  this would make a fine monochrome eh?  gl.', '2012-07-02 20:11:29.000000', NULL, 1);
