(6808564, 1022413, 97225, '<td valign="top">Congratulations on the blue ribbon. Great shot of an intriguing structure. Actually it brings to mind the front wheel of my husband''s bike after he had an accident on it(years ago).</td>', 'Congratulations on the blue ribbon. Great shot of an intriguing structure. Actually it brings to mind the front wheel of my husband''s bike after he had an accident on it(years ago).', '2012-07-04 08:53:36.000000', NULL, 0),
